package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/plans")
@Validated
public class PlanController {

    /** What the screen shows of a plan; the amount always has two decimals. Generated is how many claims
     *  it has made so far; next dates are its first five plan dates after the sheet's today, on or before
     *  its end and not skipped by a pause, oldest first. Paused is whether it is paused now. */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every,
            Integer day, LocalDate end, int generated, List<LocalDate> nextDates, boolean paused) {
        static PlanView of(Plan plan, LocalDate today) {
            return new PlanView(plan.getId(), plan.getPersonId(), plan.getAmount().toPlainString(), plan.getStart(),
                    plan.getEvery(), plan.getDay(), plan.getEnd(), plan.getGeneratedCount(),
                    plan.datesAfter(today, 5), plan.isPaused());
        }
    }

    /** A plan's fields as entered on the person's row; no start means the sheet's today. A plan has either
     *  every (days) or day (of the month, for a monthly plan). */
    public record PlanForm(@NotNull Long personId, @NotNull @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate start, Integer every, Integer day, @NotNull LocalDate end) {
    }

    /** How many claims a generate made, the claims, oldest first, and the sheet's plans as they are then. */
    public record GenerateView(int generated, List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;

    public PlanController(PlanService service) {
        this.service = service;
    }

    /** The sheet's plans in the order they were added. */
    @GetMapping
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String id = sheetId.trim();
        LocalDate today = service.today(id);
        return service.list(id).stream().map((plan) -> PlanView.of(plan, today)).toList();
    }

    /** Add a plan to a person. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PlanForm form) {
        String id = sheetId.trim();
        return PlanView.of(service.add(id, SignedInUser.name(user), form.personId(), form.amount(),
                form.start(), form.every(), form.day(), form.end()), service.today(id));
    }

    /** Pause the plan from the sheet's today. */
    @PostMapping("/{planId}/pause")
    public PlanView pause(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String id = sheetId.trim();
        return PlanView.of(service.pause(id, SignedInUser.name(user), planId, true), service.today(id));
    }

    /** Resume the plan from the sheet's today. */
    @PostMapping("/{planId}/resume")
    public PlanView resume(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long planId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String id = sheetId.trim();
        return PlanView.of(service.pause(id, SignedInUser.name(user), planId, false), service.today(id));
    }

    /** Make the plans' claims due by the sheet's today. */
    @PostMapping("/generate")
    public GenerateView generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String id = sheetId.trim();
        List<ClaimView> claims = service.generate(id, SignedInUser.name(user)).stream().map(ClaimView::of).toList();
        LocalDate today = service.today(id);
        return new GenerateView(claims.size(), claims,
                service.list(id).stream().map((plan) -> PlanView.of(plan, today)).toList());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person's plan: a claim of its amount on every plan date, up to its end. The plan dates are either the
 *  start then every N days, or, for a monthly plan, its day of the month in every month from the start's
 *  month (a day beyond the month's length falling on its last day), those before the start left out. */
@Entity
@Table(name = "person_plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** Every N days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan; null for any other. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    /** The plan dates it has made a claim for. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_plan_date", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "plan_date", nullable = false)
    private Set<LocalDate> generated = new HashSet<>();

    /** Its pauses, oldest first; one is still open while the plan is paused. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderBy("pausedOn")
    private List<PlanPause> pauses = new ArrayList<>();

    protected Plan() {
    }

    Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    /** The plan dates, oldest first, on or before both its end and the date, those a pause skips left out. */
    List<LocalDate> datesUpTo(LocalDate upTo) {
        return scheduleUpTo(upTo).stream().filter((d) -> pauses.stream().noneMatch((p) -> p.skips(d))).toList();
    }

    /** The plan dates by its schedule alone, oldest first, on or before both its end and the date. */
    private List<LocalDate> scheduleUpTo(LocalDate upTo) {
        LocalDate last = end.isBefore(upTo) ? end : upTo;
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) dates.add(d);
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate d = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!d.isBefore(start) && !d.isAfter(last)) dates.add(d);
        }
        return dates;
    }

    /** Up to the first count plan dates, oldest first, after the date and on or before its end. */
    public List<LocalDate> datesAfter(LocalDate after, int count) {
        return datesUpTo(end).stream().filter((d) -> d.isAfter(after)).limit(count).toList();
    }

    boolean hasGenerated(LocalDate date) {
        return generated.contains(date);
    }

    void markGenerated(LocalDate date) {
        generated.add(date);
    }

    /** Whether the plan is paused now. */
    public boolean isPaused() {
        return pauses.stream().anyMatch(PlanPause::isOpen);
    }

    /** Pause the plan on the date; the caller has checked it is running. */
    void pause(LocalDate on) {
        pauses.add(new PlanPause(on));
    }

    /** Resume the plan on the date; the caller has checked it is paused. */
    void resume(LocalDate on) {
        pauses.stream().filter(PlanPause::isOpen).forEach((p) -> p.resume(on));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    /** How many claims the plan has made so far. */
    public int getGeneratedCount() {
        return generated.size();
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** One pause of a plan: the day it was paused and the day it was resumed, null while still paused. The
 *  plan dates on or after the first and before the second are skipped. */
@Embeddable
public class PlanPause {

    @Column(name = "paused_on", nullable = false)
    private LocalDate pausedOn;

    @Column(name = "resumed_on")
    private LocalDate resumedOn;

    protected PlanPause() {
    }

    PlanPause(LocalDate pausedOn) {
        this.pausedOn = pausedOn;
    }

    boolean isOpen() {
        return resumedOn == null;
    }

    void resume(LocalDate on) {
        resumedOn = on;
    }

    boolean skips(LocalDate date) {
        return !date.isBefore(pausedOn) && (resumedOn == null || date.isBefore(resumedOn));
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.LockModeType;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PlanRepository extends JpaRepository<Plan, Long> {

    /** The sheet's plans in the order they were added. */
    List<Plan> findBySheetIdOrderByIdAsc(String sheetId);

    /** The plan, locked until the transaction ends, so two generates make its claim for a date once. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Plan p where p.id = :id")
    Optional<Plan> findForUpdate(@Param("id") Long id);
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ClaimService claims;
    private final Audit audit;
    private final SettingService settings;
    private final TransactionTemplate transaction;

    public PlanService(PlanRepository plans, PersonRepository people, SheetService sheets, SheetRepository sheetRows,
            ClaimService claims, Audit audit, SettingService settings, PlatformTransactionManager transactions) {
        this.plans = plans;
        this.people = people;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.claims = claims;
        this.audit = audit;
        this.settings = settings;
        this.transaction = new TransactionTemplate(transactions);
    }

    /** The sheet's plans in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's today. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.today(sheetId);
    }

    /** Add a plan to a person: refused for an amount not above 0.00, neither or both of an interval and a
     *  day of the month, an interval below 1 day, a day of the month outside 1 to 31, or an end before the
     *  start. No start means the sheet's today. */
    @Transactional
    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (amount.signum() <= 0) throw refused("The amount must be more than 0.00.");
        if ((every == null) == (day == null)) throw refused("Give either every (days) or a day of the month.");
        if (every != null && every < 1) throw refused("Every must be a whole number of days, at least 1.");
        if (day != null && (day < 1 || day > 31)) throw refused("The day of the month must be 1 to 31.");
        LocalDate from = start != null ? start : sheets.today(sheetId);
        if (end.isBefore(from)) throw refused("The end date cannot be before the start date.");
        Plan plan = plans.saveAndFlush(new Plan(sheetId, personId, amount.setScale(2), from, every, day,
                end));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + plan.getAmount().toPlainString() + " start=" + from + (day != null ? " day=" + day : " every=" + every) + " end=" + end);
        return plan;
    }

    /** Pause (true) or resume (false) the plan on the sheet's today: refused for pausing a paused plan or
     *  resuming a running one. */
    @Transactional
    public Plan pause(String sheetId, String user, long planId, boolean on) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        Plan plan = plans.findForUpdate(planId).filter((p) -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan."));
        if (on && plan.isPaused()) throw refused("The plan is paused already.");
        if (!on && !plan.isPaused()) throw refused("The plan is not paused.");
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        LocalDate today = sheets.today(sheetId);
        if (on) plan.pause(today);
        else plan.resume(today);
        plans.saveAndFlush(plan);
        audit.recordOnCommit((on ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " start=" + plan.getStart());
        return plan;
    }

    /** For every plan on the sheet, in the order they were added, make a DRAFT claim of its amount, dated
     *  the plan date with an empty note, for each plan date up to its end and the sheet's today that has
     *  none yet and no pause skips. Each claim is added by the claim form's rules, on its own: a date the form refuses is
     *  skipped and tried again next time. The claims made, oldest first; a viewer makes none. */
    public List<Claim> generate(String sheetId, String user) {
        sheets.load(sheetId);
        if (settings.roleOf(sheetId, user) == Role.VIEWER) return List.of();
        LocalDate today = sheets.today(sheetId);
        List<Claim> made = new ArrayList<>();
        for (Plan plan : plans.findBySheetIdOrderByIdAsc(sheetId)) {
            for (LocalDate date : plan.datesUpTo(today)) {
                if (plan.hasGenerated(date)) continue;
                try {
                    Claim claim = transaction.execute((status) -> generateOn(sheetId, user, plan.getId(), date));
                    if (claim != null) made.add(claim);
                } catch (ResponseStatusException refused) {
                    // The claim form refuses the date: it is tried again by the next generate.
                }
            }
        }
        return made;
    }

    /** Make the plan's claim for the date, unless it has one already. */
    private Claim generateOn(String sheetId, String user, long planId, LocalDate date) {
        Plan plan = plans.findForUpdate(planId).orElse(null);
        if (plan == null || plan.hasGenerated(date)) return null;
        Claim claim = claims.add(sheetId, user, plan.getPersonId(), plan.getAmount(), date, "", null, null, null);
        plan.markGenerated(date);
        plans.saveAndFlush(plan);
        return claim;
    }

    private static ResponseStatusException refused(String why) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, why);
    }
}
-- A plan may be paused and resumed, each on the sheet's today then. A plan date on or after the day it
-- was paused and before the day it was resumed is skipped, not postponed: generating never makes its
-- claim. Each pause is one row; resumed_on is null while the plan is still paused.
CREATE TABLE person_plan_pause (
    plan_id    BIGINT NOT NULL REFERENCES person_plan (id) ON DELETE CASCADE,
    paused_on  DATE   NOT NULL,
    resumed_on DATE
);
CREATE INDEX person_plan_pause_plan ON person_plan_pause (plan_id);
-- A person's plans: an amount, a start date, every N days (at least 1) and an end date. Generating
-- makes a DRAFT claim for each plan date (the start, then every N days) up to the end and the
-- sheet's today; person_plan_date keeps each date a plan has made its claim for, so it is made once.
CREATE TABLE person_plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    amount     DECIMAL(12, 2) NOT NULL,
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL,
    end_date   DATE           NOT NULL
);
CREATE INDEX person_plan_sheet ON person_plan (sheet_id);
CREATE TABLE person_plan_date (
    plan_id   BIGINT NOT NULL REFERENCES person_plan (id) ON DELETE CASCADE,
    plan_date DATE   NOT NULL,
    PRIMARY KEY (plan_id, plan_date)
);
-- A plan may instead run monthly on a day of the month (1 to 31): its plan dates are that day in every
-- month from the start's month, a day beyond the month's length falling on its last day, dates before
-- the start left out. Such a plan has a day_of_month and no every_days; any other has every_days only.
ALTER TABLE person_plan ALTER COLUMN every_days SET NULL;
ALTER TABLE person_plan ADD COLUMN day_of_month INT;
